mapper.select:
select a.id, a.surrogate_id, a.`number`, a.`name`, a.acl_module_id, a.url, a.type, a.menu_name, a.menu_url, a.btn_sign, a.status, a.seq, a.remark, a.operate_ip, a.creator_id, a.operator, a.create_time, a.update_time, d.name as 'acl_module_name', b.user_name as 'creator_name', c.operator as 'operator_name' from sys_acl as a left join sys_acl_module as d on (a.acl_module_id = d.surrogate_id) left join sys_user as b on (a.creator_id = b.surrogate_id) left join sys_user as c on (a.operator = c.surrogate_id)
a.surrogate_id in (
#{aclId}
)

select a.id, a.surrogate_id, a.`number`, a.`name`, a.acl_module_id, a.url, a.type, a.menu_name, a.menu_url, a.btn_sign, a.status, a.seq, a.remark, a.operate_ip, a.creator_id, a.operator, a.create_time, a.update_time, b.name as 'acl_module_name', c.account as 'creator_name', d.account as 'operator_name', d.user_name as 'nick_name' from sys_acl as a left join sys_acl_module as b on (a.acl_module_id = b.surrogate_id) left join sys_user as c on (a.creator_id = c.surrogate_id) left join sys_user as d on (a.operator = d.surrogate_id)
a.acl_module_id = #{param.aclModuleId}
a.status = #{param.status}
and ( a.`number` like concat('%',#{param.keyWords},'%') or a.`name` like concat('%',#{param.keyWords},'%') or a.remark like concat('%',#{param.keyWords},'%') )
order by seq asc

select count(1) from sys_acl as a left join sys_acl_module as d on (a.acl_module_id = d.surrogate_id) left join sys_user as b on (a.creator_id = b.surrogate_id) left join sys_user as c on (a.operator = c.surrogate_id)
a.acl_module_id = #{param.aclModuleId}
a.status = #{param.status}
and ( a.`number` like concat('%',#{param.keyWords},'%') or a.`name` like concat('%',#{param.keyWords},'%') or a.remark like concat('%',#{param.keyWords},'%') )
